javascript:!function(){document.querySelectorAll('.ai-turn-tag').forEach(el=> el.remove());const prevBtn=document.getElementById('ai-turn-clear-btn');if(prevBtn)prevBtn.remove();const utterances=[];document.querySelectorAll('.tonYlb').forEach(block=>{const userContainer=block.querySelector('.sUKAcb');const modelContainer=block.querySelector('.CKgc1d');if(userContainer)utterances.push({el:userContainer,forUser:true});if(modelContainer)utterances.push({el:modelContainer,forUser:false});});if(!utterances.length)return alert('대화를 찾지 못했습니다.');function makeTag(n,forUser){const tag=document.createElement('span');tag.className='ai-turn-tag';tag.textContent=`T${n}`;tag.setAttribute('aria-hidden','true');const hue=forUser?'#1a73e8':'#188038';const bg=forUser?'#e8f0fe':'#e6f4ea';tag.style.cssText=[`color:${hue}`,`background:${bg}`,`border:1px solid ${hue}`,'border-radius:10px','padding:1px 7px','font-size:11px','font-weight:700','font-family:monospace','line-height:1.6','vertical-align:middle','display:inline-block','margin-right:8px','margin-bottom:4px','user-select:none','pointer-events:none',].join(';');return tag;}utterances.forEach(({el,forUser},i)=>{const tag=makeTag(i + 1,forUser);el.prepend(tag);});const btn=document.createElement('button');btn.id='ai-turn-clear-btn';btn.title='턴 번호 지우기';const icon=document.createElement('s');icon.textContent='7';icon.style.cssText='font-style:normal;font-weight:700;pointer-events:none';btn.appendChild(icon);btn.style.cssText=['position:fixed','bottom:88px','right:20px','width:40px','height:40px','border-radius:50%','border:2px solid #1a73e8','background:#fff','color:#1a73e8','font-size:17px','cursor:pointer','z-index:9999','display:flex','align-items:center','justify-content:center','box-shadow:0 2px 8px rgba(0,0,0,.25)','transition:background .15s',].join(';');btn.onmouseenter=()=> btn.style.background='#e8f0fe';btn.onmouseleave=()=> btn.style.background='#fff';btn.onclick=()=>{document.querySelectorAll('.ai-turn-tag').forEach(el=> el.remove());btn.remove();};document.body.appendChild(btn);console.log(`턴 번호 ${utterances.length}개 삽입 완료`);}();